'use client';

import { useAuth } from '@/context/AuthContext';
import {
    LayoutDashboard, Users, Building2, CalendarCheck,
    ClipboardCheck, Workflow, BarChart3, FileCheck, GraduationCap
} from 'lucide-react';

const ROLE_LABELS: Record<string, string> = {
    super_admin: 'Super Admin',
    admin: 'Institution Admin',
    hod: 'Head of Department',
    faculty: 'Faculty',
    student: 'Student',
};

export default function DashboardHome() {
    const { user } = useAuth();
    if (!user) return null;

    const cards = getDashboardCards(user.role);

    return (
        <div>
            <div style={{ marginBottom: 32 }}>
                <h1 style={{ fontSize: 28, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                    Welcome back, {user.name}
                </h1>
                <p style={{ fontSize: 15, color: '#5a6a72' }}>
                    {ROLE_LABELS[user.role]} Dashboard • {user.tenant_id || 'Platform Level'}
                </p>
            </div>

            {/* Quick Stats */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 20, marginBottom: 32 }}>
                {cards.map((card, i) => (
                    <div key={i} className="card" style={{ padding: 24, position: 'relative', overflow: 'hidden' }}>
                        <div style={{
                            position: 'absolute', top: -10, right: -10,
                            width: 60, height: 60, borderRadius: '50%',
                            background: `${card.color}10`,
                        }} />
                        <div style={{
                            width: 44, height: 44, borderRadius: 10,
                            background: `${card.color}12`, color: card.color,
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            marginBottom: 14,
                        }}>
                            {card.icon}
                        </div>
                        <div style={{ fontSize: 24, fontWeight: 800, color: '#142B34', fontFamily: 'Poppins' }}>
                            {card.value}
                        </div>
                        <div style={{ fontSize: 13, color: '#8a9aa2', fontWeight: 500, marginTop: 4 }}>
                            {card.label}
                        </div>
                    </div>
                ))}
            </div>

            {/* Role-specific info */}
            <div className="card" style={{ padding: 32 }}>
                <h2 style={{ fontSize: 18, fontWeight: 700, color: '#142B34', marginBottom: 16, fontFamily: 'Poppins' }}>
                    Quick Actions
                </h2>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 16 }}>
                    {getQuickActions(user.role).map((action, i) => (
                        <a
                            key={i}
                            href={action.href}
                            style={{
                                display: 'flex', alignItems: 'center', gap: 12,
                                padding: '14px 18px', borderRadius: 10,
                                border: '1px solid #e2e6ea', background: '#fafbfc',
                                textDecoration: 'none', transition: 'all 0.2s',
                                cursor: 'pointer',
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.borderColor = '#142B34';
                                e.currentTarget.style.background = '#f0f4f7';
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.borderColor = '#e2e6ea';
                                e.currentTarget.style.background = '#fafbfc';
                            }}
                        >
                            <div style={{
                                width: 36, height: 36, borderRadius: 8,
                                background: '#142B34', color: 'white',
                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                flexShrink: 0,
                            }}>
                                {action.icon}
                            </div>
                            <div>
                                <div style={{ fontSize: 14, fontWeight: 600, color: '#142B34' }}>{action.label}</div>
                                <div style={{ fontSize: 12, color: '#8a9aa2' }}>{action.desc}</div>
                            </div>
                        </a>
                    ))}
                </div>
            </div>
        </div>
    );
}

function getDashboardCards(role: string) {
    const base = [
        { icon: <Users size={22} />, label: 'Total Users', value: '—', color: '#2563eb' },
        { icon: <CalendarCheck size={22} />, label: 'Attendance Today', value: '—', color: '#059669' },
        { icon: <ClipboardCheck size={22} />, label: 'Pending Approvals', value: '—', color: '#d97706' },
        { icon: <BarChart3 size={22} />, label: 'Reports Generated', value: '—', color: '#7c3aed' },
    ];

    if (role === 'super_admin') {
        return [
            { icon: <Building2 size={22} />, label: 'Institutions', value: '2', color: '#2563eb' },
            { icon: <Users size={22} />, label: 'Total Users', value: '7', color: '#059669' },
            { icon: <BarChart3 size={22} />, label: 'Active Tenants', value: '2', color: '#d97706' },
            { icon: <FileCheck size={22} />, label: 'System Health', value: '99.9%', color: '#7c3aed' },
        ];
    }

    if (role === 'student') {
        return [
            { icon: <CalendarCheck size={22} />, label: 'Attendance %', value: '—', color: '#059669' },
            { icon: <GraduationCap size={22} />, label: 'Internal Marks', value: '—', color: '#2563eb' },
            { icon: <Workflow size={22} />, label: 'OD Requests', value: '—', color: '#d97706' },
            { icon: <FileCheck size={22} />, label: 'Subjects', value: '—', color: '#7c3aed' },
        ];
    }

    return base;
}

function getQuickActions(role: string) {
    switch (role) {
        case 'super_admin':
            return [
                { icon: <Building2 size={16} />, label: 'Manage Institutions', desc: 'View & create tenants', href: '/dashboard/tenants' },
                { icon: <Users size={16} />, label: 'Manage Users', desc: 'View all users', href: '/dashboard/users' },
                { icon: <BarChart3 size={16} />, label: 'System Analytics', desc: 'Platform overview', href: '/dashboard' },
            ];
        case 'admin':
            return [
                { icon: <Building2 size={16} />, label: 'Academic Structure', desc: 'Departments & programs', href: '/dashboard/departments' },
                { icon: <ClipboardCheck size={16} />, label: 'Lock Marks', desc: 'Finalize approved marks', href: '/dashboard/marks-lock' },
                { icon: <FileCheck size={16} />, label: 'Compliance Reports', desc: 'Export CSV/PDF', href: '/dashboard/compliance' },
            ];
        case 'hod':
            return [
                { icon: <ClipboardCheck size={16} />, label: 'Approve Marks', desc: 'Review submissions', href: '/dashboard/marks-approval' },
                { icon: <Workflow size={16} />, label: 'Approve OD', desc: 'Pending OD requests', href: '/dashboard/od-approval' },
                { icon: <BarChart3 size={16} />, label: 'Department Stats', desc: 'Attendance defaulters', href: '/dashboard/dept-stats' },
            ];
        case 'faculty':
            return [
                { icon: <CalendarCheck size={16} />, label: 'Mark Attendance', desc: 'Today\'s sessions', href: '/dashboard/attendance' },
                { icon: <ClipboardCheck size={16} />, label: 'Submit Marks', desc: 'Internal marks entry', href: '/dashboard/marks-entry' },
                { icon: <Workflow size={16} />, label: 'OD Requests', desc: 'Approve student ODs', href: '/dashboard/od-requests' },
            ];
        case 'student':
            return [
                { icon: <CalendarCheck size={16} />, label: 'My Attendance', desc: 'View attendance %', href: '/dashboard/my-attendance' },
                { icon: <GraduationCap size={16} />, label: 'My Marks', desc: 'View locked marks', href: '/dashboard/my-marks' },
                { icon: <Workflow size={16} />, label: 'Apply OD', desc: 'Submit OD request', href: '/dashboard/apply-od' },
            ];
        default:
            return [];
    }
}
